insert into cases (id,title,category,risk_label,content,source,tags,source_url,source_title,published_at,source_kind,risk_features,prevention,script_text) values
('8862aff0-6321-4bb5-8ca0-8f80c0280a74','12321 举报受理回复','正常服务','安全','【12321网络不良与垃圾信息举报受理中心】您提交的垃圾短信举报已受理，处理结果将通过官方渠道反馈。该中心不会要求您提供银行卡、验证码或进行转账。','官方公共服务样例',ARRAY['12321', '举报', '官方回复']::text[],NULL,'自建安全案例',NULL,'seed',ARRAY['官方渠道通知', '不索取资金与凭证', '无陌生链接', '无需转账']::text[],'此类通知无需操作；如遇要求转账或索要验证码的同类信息，请通过官方渠道核实。','【12321网络不良与垃圾信息举报受理中心】您提交的垃圾短信举报已受理，处理结果将通过官方渠道反馈。该中心不会要求您提供银行卡、验证码或进行转账。'),
('d04362e1-9e69-405e-8749-c1d2f5d85a3d','12381 涉诈预警提示短信','正常服务','安全','【12381】您可能正在遭遇电信网络诈骗，请立即停止转账并与家人核实。12381 为工业和信息化部反诈预警号码，该提示不索要任何账户信息。','官方公共服务样例',ARRAY['12381', '反诈预警', '官方提示']::text[],NULL,'自建安全案例',NULL,'seed',ARRAY['官方渠道通知', '不索取资金与凭证', '无陌生链接', '无需转账']::text[],'此类通知无需操作；如遇要求转账或索要验证码的同类信息，请通过官方渠道核实。','【12381】您可能正在遭遇电信网络诈骗，请立即停止转账并与家人核实。12381 为工业和信息化部反诈预警号码，该提示不索要任何账户信息。'),
('6cdcf09e-ab47-4ab7-8713-616d772ddb05','AI换脸伪造白富美人设网恋诈骗十三万','AI换脸','诈骗','被告人孙某在网络游戏中结识受害人后，虚构“白富美”人设，通过伪造身份证件、利用虚拟人脸技术与受害人视频聊天，骗取其信任并确立恋爱关系。自2024年11月起虚构各种事由索取钱财，累计诈骗近十三万元后失联，法院以诈骗罪判处其有期徒刑三年、缓刑四年。','人民法院报案例（忻府区法院转载）',ARRAY['AI换脸', '网恋', '伪造身份证件', '视频通话']::text[],'https://xzxffy.shanxify.gov.cn/article/detail/2025/11/id/9091051.shtml','利用“AI换脸”诈骗网恋对象 女子被判刑罚（人民法院报）','2025-11-28','official',ARRAY['AI换脸伪造视频形象', '伪造身份证件', '虚构优质人设', '以恋爱关系索财']::text[],'视频中的人脸与声音都可以被伪造，涉及转账时务必通过多种方式核验身份，不要仅凭视频通话确认对方。','视频里你看到的就是我，我怎么可能骗你，先借我点钱周转'),
('b1ab57c7-2bc1-4e64-852f-08519226e712','ETC到期失效短信钓鱼骗局','ETC','诈骗','收到短信提示ETC即将到期失效，点击链接完成续约，页面为伪造网站，输入银行卡信息直接被盗刷。','反诈公开案例',ARRAY['ETC到期', '续约短信', '伪造网站']::text[],'https://m.gmw.cn/toutiao/2025-02/06/content_1303963828.htm','车主注意！警方重要提醒（光明网）','2025-02-06','media',ARRAY['短信称账户异常或到期', '附带短链接', '仿冒ETC认证页面', '索要身份证与银行卡']::text[],'ETC业务请通过发行方官方App或客服办理；不要点击短信链接填写身份证与银行卡。','收到短信提示ETC即将到期失效，点击链接完成续约，页面为伪造网站，输入银行卡信息直接被盗刷。'),
('2288206b-0ea4-49d2-a467-bd332ad5634b','ETC异常扣费短信钓鱼诈骗','ETC','诈骗','发送ETC扣费异常、账户冻结短信，附带钓鱼短链接，诱导用户点击链接填写身份证、银行卡，盗取个人财产。','反诈公开案例',ARRAY['ETC', '短信钓鱼', '异常扣费', '短链接']::text[],'https://m.gmw.cn/toutiao/2025-02/06/content_1303963828.htm','车主注意！警方重要提醒（光明网）','2025-02-06','media',ARRAY['短信称账户异常或到期', '附带短链接', '仿冒ETC认证页面', '索要身份证与银行卡']::text[],'ETC业务请通过发行方官方App或客服办理；不要点击短信链接填写身份证与银行卡。','发送ETC扣费异常、账户冻结短信，附带钓鱼短链接，诱导用户点击链接填写身份证、银行卡，盗取个人财产。'),
('425a5647-6e88-4ce2-a5ad-ab61c8a116f1','ETC异常扣费诈骗','ETC','诈骗','收到短信提示ETC账户冻结/异常扣费，点击链接完成解冻，页面要求输入身份证银行卡。','反诈中心',ARRAY['ETC', '短信链接', '解冻']::text[],'https://m.gmw.cn/toutiao/2025-02/06/content_1303963828.htm','车主注意！警方重要提醒（光明网）','2025-02-06','media',ARRAY['短信称账户异常或到期', '附带短链接', '仿冒ETC认证页面', '索要身份证与银行卡']::text[],'ETC业务请通过发行方官方App或客服办理；不要点击短信链接填写身份证与银行卡。','收到短信提示ETC账户冻结/异常扣费，点击链接完成解冻，页面要求输入身份证银行卡。'),
('0676c6a9-ebd3-4334-829d-d7675eed495e','gov.cn 中国政府网政策公告','正常服务','安全','https://www.gov.cn/ 为中华人民共和国中央人民政府官方网站，发布政策文件、政务公开与便民服务信息。该网站不会要求访客填写银行卡号、验证码，也不会索要转账。','公开政务网站说明',ARRAY['政务', '官网', 'gov.cn', '无风险']::text[],NULL,'自建安全案例',NULL,'seed',ARRAY['官方渠道通知', '不索取资金与凭证', '无陌生链接', '无需转账']::text[],'此类通知无需操作；如遇要求转账或索要验证码的同类信息，请通过官方渠道核实。','https://www.gov.cn/ 为中华人民共和国中央人民政府官方网站，发布政策文件、政务公开与便民服务信息。该网站不会要求访客填写银行卡号、验证码，也不会索要转账。'),
('ba78fdd5-bfad-4183-9cea-6a78d6973ef8','下载不明投资App后多次转账至指定平台无法提现','虚拟货币','诈骗','受害人在诈骗分子指引下下载了来源不明的投资App，随后按对方提供的账户与平台地址多次转账，既有银行人民币转账，也有USDT虚拟货币交易。直到发现账户资金无法提现、所谓投资项目没有实际价值，才意识到被骗并报警。','广州市公安局警情通报',ARRAY['不明App', 'USDT', '无法提现', '指定平台']::text[],'https://gaj.gz.gov.cn/zzzq/jwzx/content/post_10736182.html','轻信“元宇宙”投资骗局损失百万 广州番禺警方循线追踪全额挽损（广州市公安局）','2026-03-21','official',ARRAY['引导下载非官方App', '指定账户与平台转账', '虚拟货币转移资金']::text[],'投资理财请使用持牌机构的官方App；不要下载陌生人推荐的软件，更不要向私人账户或虚拟货币地址转账。','下载这个App，钱转到平台账户，收益随时能提'),
('91d2edc4-a562-48d0-9937-c9e6d91f6bd9','以医保补贴到账为名骗取银行卡验证码','医保社保','诈骗','骗子群发“医保补贴到账”“报销款未领取”“居民补充医疗保险已申请”等信息，要求点击链接填写银行卡号、验证码以领取补贴，实际是将受害人银行卡与支付账户绑定后盗刷资金。','淮北市公安局警情提示',ARRAY['医保补贴', '报销款', '验证码', '盗刷']::text[],'https://gaj.huaibei.gov.cn/jwzx/jfts/57931954.html','警方提示：别信！医保诈骗新套路！（淮北市公安局）','2025-05-20','official',ARRAY['虚假补贴通知', '诱导填写验证码', '关联账户盗刷']::text[],'医保补贴不会通过短信链接发放，也不需要提供银行卡验证码；收到此类信息直接删除。','您有一笔医保补贴未领取，点击链接填写银行卡和验证码即可到账'),
('5c2fdd6e-a522-493c-a503-e0cf722da092','以屏幕共享远程操作方式转走机票退款受害人资金','机票退改签','诈骗','警方提示，此类诈骗中嫌疑人在非法获取公民机票信息后，以“航班故障、退改签给赔偿”为幌子，诱使受害人下载不熟悉的手机App，再通过屏幕共享、后台窃密等方式，远程转走受害人账户中的资金。','央视新闻曝光案例（光明网转载）',ARRAY['屏幕共享', '远程操控', '航班故障', '盗刷']::text[],'https://m.gmw.cn/2026-01/07/content_1304294170.htm','从“赔你钱”到“让你贷” 总台曝光机票退改签诈骗（央视新闻）','2026-01-07','media',ARRAY['诱导下载陌生App', '要求屏幕共享', '后台窃密远程转账']::text[],'任何要求开启屏幕共享的操作都应立即拒绝；退改签只通过官方渠道办理，不要安装陌生人推荐的App。','你开个屏幕共享，我教你怎么操作退款'),
('4888dbee-0d3f-4fa2-93ea-28ebdf193caa','以注册费会员费名义层层加码的游戏交易诈骗','网络游戏交易','诈骗','诈骗分子在社交和游戏平台发布低价充值、免费领取道具的广告，诱导玩家到指定平台或私下交易。随后以操作失误、账号等级不够等理由，要求支付注册费、会员费、解冻费，累计骗取三万余元后拉黑受害人。','公安部刑侦局提示（光明网转载）',ARRAY['低价充值', '会员费', '注册费', '拉黑']::text[],'https://m.gmw.cn/2025-07/29/content_1304096705.htm','警方提醒：警惕网络游戏虚假交易类诈骗（公安部刑侦局）','2025-07-29','official',ARRAY['低价充值诱导', '脱离官方平台', '编造操作失误理由', '层层收费后拉黑']::text[],'游戏充值与道具交易请在游戏内官方商城完成；私下交易和第三方“低价渠道”均存在被骗风险。','充值要先开会员、交注册费，不然账号用不了'),
('e3ac5cd2-5abb-4fd0-aed6-3a34f3d85826','以虚拟矿机挖币与虚拟人物打卡日结薪酬为诱饵的投资骗局','虚拟货币','诈骗','诈骗分子虚构“数字矿机挖币”“虚拟人物打卡日结薪酬”等投资与收益模式，宣称投入后可按日获得稳定回报，并以平台内收益截图营造真实感。受害人投入资金后，所谓项目毫无实际价值，账户资金也无法提现。','广州市公安局警情通报',ARRAY['数字矿机', '日结薪酬', '虚假收益', '无法提现']::text[],'https://gaj.gz.gov.cn/zzzq/jwzx/content/post_10736182.html','轻信“元宇宙”投资骗局损失百万 广州番禺警方循线追踪全额挽损（广州市公安局）','2026-03-21','official',ARRAY['虚构稳定收益模式', '伪造收益数据', '提现受阻']::text[],'任何声称“日结收益”“稳定产币”的项目都应高度警惕；投资前核实平台资质，不要向陌生平台转账。','买矿机每天产币，打卡还有日结工资，回本很快'),
('d5b058a6-c89d-4456-a9f9-471702ccf726','以退费需先交保证金手续费为由骗取转账','机票退改签','诈骗','国家反诈中心总结的话术显示，诈骗分子在取得信任并制造行程危机感后，会以“航班退费需先交保证金”“改签需先交手续费”等理由骗取转账，或发送链接要求填写个人信息、输入二维码与验证码，从而转走账户资金。','央视新闻曝光案例（光明网转载）',ARRAY['保证金', '手续费', '验证码', '话术套路']::text[],'https://m.gmw.cn/2026-01/07/content_1304294170.htm','从“赔你钱”到“让你贷” 总台曝光机票退改签诈骗（央视新闻）','2026-01-07','media',ARRAY['以退费为名先收费', '制造行程危机感', '诱导填写验证码']::text[],'正规退改签不会要求先交保证金或手续费；凡提及“保证金”“手续费”“验证码”的客服电话都应立即挂断。','退费要先把保证金交一下，改签的话还要交手续费'),
('83d0bb82-20ed-43a1-83f2-526cb9841ed3','伪造医保政策文件诱导下载木马APP','医保社保','诈骗','骗子以“医保新规”“系统升级”为借口，要求参保人下载所谓政策文件或专用App，这些附件与安装包内嵌木马病毒，一旦下载安装，个人信息与短信验证码即可能被窃取，进而造成资金损失。','淮北市公安局警情提示',ARRAY['医保新规', '木马APP', '系统升级', '附件']::text[],'https://gaj.huaibei.gov.cn/jwzx/jfts/57931954.html','警方提示：别信！医保诈骗新套路！（淮北市公安局）','2025-05-20','official',ARRAY['伪造政策通知', '诱导安装木马应用', '窃取个人信息与验证码']::text[],'政务与医保业务只通过官方应用商店下载的官方App办理；不要安装陌生来源的安装包或打开不明附件。','医保系统升级了，下载这个App完善信息，不然后面报销用不了'),
('0f9bff9e-42c1-4348-9600-5a079d8718c8','伪造身份证件与虚拟人脸骗取网恋对象信任','AI换脸','诈骗','案件中被告人通过伪造身份证件、配合虚拟人脸技术进行视频通话，使受害人相信其真实身份与外貌，进而建立恋爱关系并持续实施诈骗。法院认定其利用AI换脸、语音合成等新技术手段虚构事实、骗取财物，构成诈骗罪。','人民法院报案例（忻府区法院转载）',ARRAY['AI换脸', '伪造证件', '身份核验', '恋爱诈骗']::text[],'https://xzxffy.shanxify.gov.cn/article/detail/2025/11/id/9091051.shtml','利用“AI换脸”诈骗网恋对象 女子被判刑罚（人民法院报）','2025-11-28','official',ARRAY['证件照片可伪造', '视频画面可换脸', '以恋爱关系掩护索财']::text[],'身份证照片、视频画面均不能作为身份核验依据；网恋对象频繁索要钱财时，应提高警惕并及时报警。','身份证照片发你了，视频也通了，你还不信我？'),
('528f47e3-6a8f-4a63-87b4-5fee9e9903c4','元宇宙虚拟房产投资骗局骗取一百一十四万','虚拟货币','诈骗','受害人轻信所谓“元宇宙新型投资平台”，对方虚构“虚拟房产增值”“数字矿机挖币”“虚拟人物打卡日结薪酬”等投资项目，以高回报、低风险为噱头进行话术洗脑。受害人下载不明App后，通过银行转账和USDT虚拟货币交易多次转入资金，累计损失一百一十四万元。','广州市公安局警情通报',ARRAY['元宇宙', '虚拟房产', 'USDT', '高回报']::text[],'https://gaj.gz.gov.cn/zzzq/jwzx/content/post_10736182.html','轻信“元宇宙”投资骗局损失百万 广州番禺警方循线追踪全额挽损（广州市公安局）','2026-03-21','official',ARRAY['借元宇宙等新概念包装', '虚构虚拟房产与矿机项目', '通过USDT转移资金', '承诺高回报低风险']::text[],'新兴概念不等于投资机会；凡是承诺高回报、低风险且要求转入虚拟货币的项目，基本都是诈骗。','元宇宙虚拟房产马上升值，矿机每天产币，稳赚不赔'),
('30f61a31-92a3-44c0-835f-aa8bf694c884','公司内部会议通知','正常服务','安全','各位同事：明天上午10:00在三楼第二会议室召开项目周会，请携带本周工作汇报。会议无需缴费、无需点击外部链接，也不会索要任何账户信息。','企业内部通知样例',ARRAY['会议通知', '内部', '无风险']::text[],NULL,'自建安全案例',NULL,'seed',ARRAY['官方渠道通知', '不索取资金与凭证', '无陌生链接', '无需转账']::text[],'此类通知无需操作；如遇要求转账或索要验证码的同类信息，请通过官方渠道核实。','各位同事：明天上午10:00在三楼第二会议室召开项目周会，请携带本周工作汇报。会议无需缴费、无需点击外部链接，也不会索要任何账户信息。'),
('912cb46e-feeb-4153-bdfb-5da53e9c60f7','兼职刷单小额返利诱导大额垫付','刷单','诈骗','骗子在社交软件发布刷单兼职广告，先用小额任务返还佣金建立信任，随后下发大额连单任务，要求受害人不断充值垫付，最后以任务未完成、账户冻结为由拒绝返还本金并将受害人拉黑。','反诈知识库种子',ARRAY['刷单', '垫付', '连单', '返利']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['小额返利建立信任', '诱导大额垫付', '以任务卡单/冻结拒返款', '脱离平台私下转账']::text[],'任何要求先垫付本金的兼职刷单都是诈骗；不要为陌生任务充值转账，发现被骗立即报警。','骗子在社交软件发布刷单兼职广告，先用小额任务返还佣金建立信任，随后下发大额连单任务，要求受害人不断充值垫付，最后以任务未完成、账户冻结为由拒绝返还本金并将受害人拉黑。'),
('bd6ee0d9-f86c-410f-8a49-57fa648c9772','兼职刷单被引导至博彩平台充值一百零八万','刷单','诈骗','受害人被拉入兼职刷单微信群，群内客服诱导其向所谓网络博彩平台充值刷流水。前期小额充值均能获利并顺利提现，随着本金不断加大，累计充值达一百零八万元，待准备提现时发现账户无法操作并被踢出群聊。','国家反诈中心十大高发诈骗（晋中市公安局转载）',ARRAY['刷单', '博彩平台', '刷流水', '无法提现']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['以兼职刷单引流', '转入博彩平台刷流水', '小额可提现建立信任', '大额后封号']::text[],'所有刷单都是诈骗；被要求向博彩平台充值刷流水的，属于典型诈骗兼违法赌博，应立即停止并报警。','充值刷流水就能赚差价，前面几单都能提现，放心做'),
('e0d4bebf-7640-4702-8908-6a02249a4c27','冒充ETC客服，办理退费返还诈骗','ETC','诈骗','骗子声称ETC多扣通行费，可以办理退费，引导提供银行卡和验证码，借机盗刷账户余额。','反诈公开案例',ARRAY['ETC退费', '多扣通行费', '验证码泄露']::text[],'https://m.gmw.cn/toutiao/2025-02/06/content_1303963828.htm','车主注意！警方重要提醒（光明网）','2025-02-06','media',ARRAY['短信称账户异常或到期', '附带短链接', '仿冒ETC认证页面', '索要身份证与银行卡']::text[],'ETC业务请通过发行方官方App或客服办理；不要点击短信链接填写身份证与银行卡。','骗子声称ETC多扣通行费，可以办理退费，引导提供银行卡和验证码，借机盗刷账户余额。'),
('e49c9ea4-d356-408c-860b-7c76b6e96521','冒充ETC工作人员要求升级账户','ETC','诈骗','冒充ETC客服打电话，告知ETC需要升级，引导添加微信或者访问非官方网站，索要验证码转账。','反诈公开案例',ARRAY['ETC升级', '冒充工作人员', '电话诈骗']::text[],'https://m.gmw.cn/toutiao/2025-02/06/content_1303963828.htm','车主注意！警方重要提醒（光明网）','2025-02-06','media',ARRAY['短信称账户异常或到期', '附带短链接', '仿冒ETC认证页面', '索要身份证与银行卡']::text[],'ETC业务请通过发行方官方App或客服办理；不要点击短信链接填写身份证与银行卡。','冒充ETC客服打电话，告知ETC需要升级，引导添加微信或者访问非官方网站，索要验证码转账。'),
('70d627fd-5b5e-4a82-80bd-1ba9d533688c','冒充公安发送伪造逮捕证实施恐吓诈骗','冒充公检法','诈骗','冒充公安，通过聊天软件发送伪造逮捕证、拘留文书，恐吓受害人不能告诉家人，要求转账资金自清。','反诈公开案例',ARRAY['伪造逮捕证', '恐吓施压', '资金自清']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['伪造法律文书', '制造恐慌与保密要求', '资金清查/安全账户', '视频笔录或隔离审查']::text[],'公检法不会电话办案，不存在安全账户，不会要求转账或保密；挂断并拨打110核实。','冒充公安，通过聊天软件发送伪造逮捕证、拘留文书，恐吓受害人不能告诉家人，要求转账资金自清。'),
('c098158c-e1f2-4c85-ad05-68cee8eb0ce5','冒充公安称涉嫌犯罪要求资金清查','冒充公检法','诈骗','骗子冒充公安机关或检察院工作人员来电，谎称受害人涉嫌洗钱等犯罪，出示伪造的法律文书制造恐慌，要求将资金转入所谓安全监管账户接受清查，并叮嘱不得告知家人，转账后资金无法追回。','反诈知识库种子',ARRAY['冒充公检法', '资金清查', '安全账户', '伪造文书']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['伪造法律文书', '制造恐慌与保密要求', '资金清查/安全账户', '视频笔录或隔离审查']::text[],'公检法不会电话办案，不存在安全账户，不会要求转账或保密；挂断并拨打110核实。','骗子冒充公安机关或检察院工作人员来电，谎称受害人涉嫌洗钱等犯罪，出示伪造的法律文书制造恐慌，要求将资金转入所谓安全监管账户接受清查，并叮嘱不得告知家人，转账后资金无法追回。'),
('439443e8-aab0-4c63-95d7-14a45f4196a8','冒充公检法涉嫌犯罪要求资金清查','冒充公检法','诈骗','冒充警察、检察院来电，谎称个人涉嫌洗钱犯罪，出示伪造法律文书，要求把钱转入安全监管账户做资金清查，实际是诈骗转账。','反诈公开案例',ARRAY['冒充公检法', '洗钱', '安全账户', '电话恐吓']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['伪造法律文书', '制造恐慌与保密要求', '资金清查/安全账户', '视频笔录或隔离审查']::text[],'公检法不会电话办案，不存在安全账户，不会要求转账或保密；挂断并拨打110核实。','冒充警察、检察院来电，谎称个人涉嫌洗钱犯罪，出示伪造法律文书，要求把钱转入安全监管账户做资金清查，实际是诈骗转账。'),
('3fadbedb-57b1-44e4-aacb-f23c59553955','冒充出入境公安，名下银行卡涉案诈骗','冒充公检法','诈骗','冒充出入境公安来电，声称受害人名下银行卡涉嫌犯罪，要求隔离审查，诱导资金转入所谓监管账户。','反诈公开案例',ARRAY['出入境公安', '银行卡涉案', '隔离审查']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['伪造法律文书', '制造恐慌与保密要求', '资金清查/安全账户', '视频笔录或隔离审查']::text[],'公检法不会电话办案，不存在安全账户，不会要求转账或保密；挂断并拨打110核实。','冒充出入境公安来电，声称受害人名下银行卡涉嫌犯罪，要求隔离审查，诱导资金转入所谓监管账户。'),
('be03a22f-f501-484e-a682-df621ff4be3a','冒充医保部门称可二次报销诱导绑定银行卡','医保社保','诈骗','受害人接到以95开头的七位数电话，对方自称医保部门工作人员，称可帮忙查看补充医保电子保单、报销剩余部分还能二次报销，随后指导其关注公众号并填写客服邀请码。当对方要求绑定银行卡时，受害人产生怀疑并挂断电话。','淮北市公安局警情提示',ARRAY['医保', '二次报销', '公众号', '绑定银行卡']::text[],'https://gaj.huaibei.gov.cn/jwzx/jfts/57931954.html','警方提示：别信！医保诈骗新套路！（淮北市公安局）','2025-05-20','official',ARRAY['冒用医保部门身份', '以二次报销为诱饵', '引导关注公众号填邀请码', '索要银行卡绑定']::text[],'医保报销一律通过医保经办机构或官方App办理，不会电话引导关注公众号、填写邀请码或绑定银行卡。','我是医保局的，你的报销还有剩余可以二次报销，关注公众号填个邀请码，再绑下银行卡'),
('e7d9838d-8a4a-4446-9216-79a71008ecb2','冒充品牌公众号抽奖中奖诈骗','中奖','诈骗','不法分子仿冒知名品牌公众号推送中奖通知，谎称用户抽中手机或现金大奖，要求先行支付运费、税费、保证金后才能领奖，转账完成后对方立即拉黑，奖品始终不会发放。','反诈知识库种子',ARRAY['中奖', '仿冒公众号', '运费税费', '保证金']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['天降中奖通知', '领奖前先收费', '运费/税费/保证金', '仿冒品牌公众号']::text[],'正规抽奖不会要求先交运费、税费或保证金；不要点击短信中的领奖链接。','不法分子仿冒知名品牌公众号推送中奖通知，谎称用户抽中手机或现金大奖，要求先行支付运费、税费、保证金后才能领奖，转账完成后对方立即拉黑，奖品始终不会发放。'),
('66e273c2-ed42-4e23-bc8e-c1305d5fc755','冒充售后客服，以换货为由索要验证码','冒充客服','诈骗','冒充商品售后客服，说商品损坏可以换货，需要短信验证码核验身份，拿到验证码直接盗刷账户。','反诈公开案例',ARRAY['换货售后', '短信验证码', '身份核验']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['准确报出订单信息', '订单异常/质量问题退款', '诱导点击陌生链接', '索要验证码或屏幕共享']::text[],'退款理赔请登录官方App核实；任何人索要验证码、要求共享屏幕的都是诈骗。','冒充商品售后客服，说商品损坏可以换货，需要短信验证码核验身份，拿到验证码直接盗刷账户。'),
('23fcf0e4-fcb0-4203-a743-9a7efaed08cf','冒充培训机构办理退费退款','退费','诈骗','冒充培训机构工作人员，说机构倒闭可以办理学费退费，但是要先缴纳手续费，诱导转账，没有任何退款到账。','反诈公开案例',ARRAY['教育退费', '培训机构', '手续费']::text[],'http://hn.people.com.cn/n2/2025/0826/c406630-41333223.html','培训机构主动退费？当心落入“课程退费”诈骗陷阱（人民网湖南频道）','2025-08-26','media',ARRAY['机构倒闭可退费', '先交手续费/保证金', '扫码进群下载APP', '验资名义转账']::text[],'退费请通过原购买平台或机构官方渠道申请；要求先交手续费、保证金的一律拒绝。','冒充培训机构工作人员，说机构倒闭可以办理学费退费，但是要先缴纳手续费，诱导转账，没有任何退款到账。'),
('e232b143-ed30-47b9-8307-c65e616176d0','冒充客服以注销校园贷记录为由诱导贷款转账','注销校园贷','诈骗','受害人接到自称支付平台客服的电话，对方称其有“校园贷”记录需要注销、否则影响征信，并能准确说出其个人信息。受害人按要求开启会议软件共享屏幕，在多个网贷平台申请贷款后转入对方提供的四个陌生账户，损失近四万元。','国家反诈中心十大高发诈骗（晋中市公安局转载）',ARRAY['注销校园贷', '征信', '共享屏幕', '网贷']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['冒充电商或支付客服', '以征信施压', '诱导共享屏幕', '指导网贷后转账']::text[],'不存在“注销校园贷”业务；凡是称不注销就影响征信、并要求转账或共享屏幕的，一律是诈骗。','你名下有校园贷记录，不注销会上征信黑名单，按我说的操作就能清掉'),
('2c793ddf-d738-4031-853e-389fc664a794','冒充客服谎称订单涉嫌违法需要处理','冒充客服','诈骗','冒充平台客服来电，称受害人购买商品涉嫌违禁品，需要配合资金核验，诱导转账到所谓安全账户。','反诈公开案例',ARRAY['订单涉嫌违法', '资金核验', '冒充平台客服']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['准确报出订单信息', '订单异常/质量问题退款', '诱导点击陌生链接', '索要验证码或屏幕共享']::text[],'退款理赔请登录官方App核实；任何人索要验证码、要求共享屏幕的都是诈骗。','冒充平台客服来电，称受害人购买商品涉嫌违禁品，需要配合资金核验，诱导转账到所谓安全账户。'),
('307520b2-9102-4651-acb9-2ce89f56e68d','冒充工友以安排司机岗位收取报名服装费','冒充熟人','诈骗','嫌疑人得知旧工友正在找工作，便复用同一套路，谎称可以介绍给领导开车的工作，以缴纳报名费、服装费等名义骗取一万七千余元，随后又以帮忙办理毕业证为由继续索要钱款。','中国警察网通报案例',ARRAY['冒充熟人', '介绍工作', '报名费', '服装费']::text[],'https://daan.cpd.com.cn/dajs/825/t_1197794.html','一人分饰三角，男子专门“杀熟”（中国警察网-人民公安报）','2025-08-22','official',ARRAY['利用熟人关系降低戒心', '虚假岗位名义收费', '连环索要费用']::text[],'熟人介绍工作也要核实单位与岗位真实性；任何以报名费、服装费、押金为先决条件的招工，都应当警惕。','我给领导开车，能帮你介绍一下，先交报名费和服装费'),
('3d97c575-4bdb-4051-9c83-462104b7b86d','冒充平台KYC身份核验冻结账户','KYC','诈骗','冒充互联网平台，通知用户账号KYC身份信息不全，账户即将冻结，引导跳转第三方页面，提交身份证、人脸、银行卡信息。','反诈公开案例',ARRAY['KYC', '身份核验', '账号冻结', '信息泄露']::text[],'https://news.youth.cn/fzlm/202605/t20260528_16684058.htm','刷个脸，竟卷入跨境诈骗大案（中国青年网）','2026-05-28','media',ARRAY['账户信息不全将被冻结', '跳转外部页面补全', '采集人脸与银行卡', '要求转账做流水核验']::text[],'实名认证只在官方App内完成；不会要求转账，也不会通过外部链接采集人脸信息。','冒充互联网平台，通知用户账号KYC身份信息不全，账户即将冻结，引导跳转第三方页面，提交身份证、人脸、银行卡信息。'),
('5cedb846-cd1d-412b-acef-0c5a112b206f','冒充平台客服谎称会员扣费可退款','冒充客服','诈骗','冒充视频平台客服，告知用户误开通年度会员，不关闭会自动扣费，引导点击陌生链接操作退款，盗取账号资金。','反诈公开案例',ARRAY['会员扣费', '误开通', '虚假退款链接']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['准确报出订单信息', '订单异常/质量问题退款', '诱导点击陌生链接', '索要验证码或屏幕共享']::text[],'退款理赔请登录官方App核实；任何人索要验证码、要求共享屏幕的都是诈骗。','冒充视频平台客服，告知用户误开通年度会员，不关闭会自动扣费，引导点击陌生链接操作退款，盗取账号资金。'),
('ac6c13ec-0625-479f-9778-bdcffeb913f0','冒充快递员谎称快递丢失主动理赔','快递理赔','诈骗','骗子冒充快递公司工作人员，电话或短信告知受害人的包裹在运输中丢失或损坏，主动提出高额理赔，随后发送仿冒链接或要求提供银行卡号、短信验证码，进而盗刷受害人账户资金。','反诈知识库种子',ARRAY['快递理赔', '包裹丢失', '钓鱼链接', '验证码']::text[],'http://www.pazjw.gov.cn/shuoan/202609/t20260927_31936970.shtml','“三倍理赔”有猫腻 假客服设真骗局（人民公安报，平安浙江网转载）','2026-09-27','official',ARRAY['冒充快递客服', '主动高额理赔', '钓鱼链接/陌生APP', '索要银行卡与验证码']::text[],'快递理赔由寄件方与快递公司处理；接到主动理赔电话请挂断并登录官方物流平台核实。','骗子冒充快递公司工作人员，电话或短信告知受害人的包裹在运输中丢失或损坏，主动提出高额理赔，随后发送仿冒链接或要求提供银行卡号、短信验证码，进而盗刷受害人账户资金。'),
('9b0f4025-a29a-475b-95a1-d0b05aa07d01','冒充快递客服，谎称包裹含有违禁品','快递理赔','诈骗','冒充快递工作人员来电，说你的快递查出违禁物品，要配合理赔调查，诱导转账做资金清查。','反诈公开案例',ARRAY['快递违禁品', '调查理赔', '冒充快递']::text[],'http://www.pazjw.gov.cn/shuoan/202609/t20260927_31936970.shtml','“三倍理赔”有猫腻 假客服设真骗局（人民公安报，平安浙江网转载）','2026-09-27','official',ARRAY['冒充快递客服', '主动高额理赔', '钓鱼链接/陌生APP', '索要银行卡与验证码']::text[],'快递理赔由寄件方与快递公司处理；接到主动理赔电话请挂断并登录官方物流平台核实。','冒充快递工作人员来电，说你的快递查出违禁物品，要配合理赔调查，诱导转账做资金清查。'),
('40bcbe85-de97-4223-9103-b46970ef915a','冒充快递客服谎称包裹丢失理赔','快递理赔','诈骗','冒充快递公司客服，告知用户快递丢失，主动提出高额理赔，引导点击陌生链接、提供银行卡信息，实施盗刷。','反诈公开案例',ARRAY['快递丢失', '理赔', '冒充快递']::text[],'http://www.pazjw.gov.cn/shuoan/202609/t20260927_31936970.shtml','“三倍理赔”有猫腻 假客服设真骗局（人民公安报，平安浙江网转载）','2026-09-27','official',ARRAY['冒充快递客服', '主动高额理赔', '钓鱼链接/陌生APP', '索要银行卡与验证码']::text[],'快递理赔由寄件方与快递公司处理；接到主动理赔电话请挂断并登录官方物流平台核实。','冒充快递公司客服，告知用户快递丢失，主动提出高额理赔，引导点击陌生链接、提供银行卡信息，实施盗刷。'),
('aaf70802-2678-4157-9b52-43457625ddde','冒充支付平台KYC补全信息诈骗','KYC','诈骗','短信通知支付账号KYC信息过期，点击链接补全人脸和银行卡资料，钓鱼页面收集个人敏感信息。','反诈公开案例',ARRAY['KYC过期', '支付账号', '人脸采集钓鱼']::text[],'https://news.youth.cn/fzlm/202605/t20260528_16684058.htm','刷个脸，竟卷入跨境诈骗大案（中国青年网）','2026-05-28','media',ARRAY['账户信息不全将被冻结', '跳转外部页面补全', '采集人脸与银行卡', '要求转账做流水核验']::text[],'实名认证只在官方App内完成；不会要求转账，也不会通过外部链接采集人脸信息。','短信通知支付账号KYC信息过期，点击链接补全人脸和银行卡资料，钓鱼页面收集个人敏感信息。'),
('5a5b7c41-ed41-4877-a7e2-e1c278f3e67e','冒充法院，谎称涉嫌传票犯罪，视频笔录诈骗','冒充公检法','诈骗','冒充法院工作人员，说收到法院传票涉嫌犯罪，开启视频通话做笔录，恐吓受害人转移资金到安全账户。','反诈公开案例',ARRAY['法院传票', '视频笔录', '冒充法院']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['伪造法律文书', '制造恐慌与保密要求', '资金清查/安全账户', '视频笔录或隔离审查']::text[],'公检法不会电话办案，不存在安全账户，不会要求转账或保密；挂断并拨打110核实。','冒充法院工作人员，说收到法院传票涉嫌犯罪，开启视频通话做笔录，恐吓受害人转移资金到安全账户。'),
('5535ef26-36ba-4787-bee1-5d280ce7ac1c','冒充海外海淘平台客服退款诈骗','冒充客服','诈骗','冒充海淘跨境购物平台客服，说海关扣货，要办理退款补偿，发送境外钓鱼链接，套取银行卡信息。','反诈公开案例',ARRAY['海淘', '海关扣货', '境外钓鱼链接']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['准确报出订单信息', '订单异常/质量问题退款', '诱导点击陌生链接', '索要验证码或屏幕共享']::text[],'退款理赔请登录官方App核实；任何人索要验证码、要求共享屏幕的都是诈骗。','冒充海淘跨境购物平台客服，说海关扣货，要办理退款补偿，发送境外钓鱼链接，套取银行卡信息。'),
('e6f5dce6-af87-4c3c-a3e6-e50d52ca547c','冒充理财大师承诺内幕消息要求线下交付现金','虚假投资理财','诈骗','嫌疑人冒充理财大师，谎称可以代理炒股并有“高手指导”和“内幕消息”，承诺收益率不低于百分之十，但要求受害人必须通过其指定账户购买。为规避资金监管，最终要求受害人取现后线下交付现金。','人民网四川频道报道',ARRAY['理财大师', '内幕消息', '线下取现', '指定账户']::text[],'http://sc.people.com.cn/n2/2025/1115/c345509-41412377.html','警惕！虚假投资理财诈骗成新套路（人民网四川频道）','2025-11-15','media',ARRAY['冒充理财专家', '承诺保底高收益', '要求走指定账户', '诱导线下现金交付']::text[],'正规证券投资必须通过持牌机构开户交易；承诺保本高收益、要求转账到个人账户或线下交付现金的，都是诈骗。','跟着我炒股，内部消息，收益不低于10%，但必须走我指定的账户'),
('f7112536-4747-4950-a570-0ccb489a9c22','冒充电商客服共享屏幕盗刷资金','冒充客服','诈骗','冒充网购客服打电话说订单异常需要退款，诱导受害人开启手机共享屏幕，远程查看银行卡、验证码，直接盗刷银行卡余额。','反诈公开案例',ARRAY['共享屏幕', '远程操控', '订单异常']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['准确报出订单信息', '订单异常/质量问题退款', '诱导点击陌生链接', '索要验证码或屏幕共享']::text[],'退款理赔请登录官方App核实；任何人索要验证码、要求共享屏幕的都是诈骗。','冒充网购客服打电话说订单异常需要退款，诱导受害人开启手机共享屏幕，远程查看银行卡、验证码，直接盗刷银行卡余额。'),
('afa69073-74d1-42aa-aab8-6cc4ca0cd972','冒充电商客服谎称订单异常办理退款','冒充客服','诈骗','骗子冒充电商平台客服，准确报出受害人订单信息后谎称订单异常需要退款，诱导点击陌生链接填写银行卡与验证码，或要求开启屏幕共享远程操作，最终盗取账户资金。','反诈知识库种子',ARRAY['冒充客服', '订单异常', '退款', '屏幕共享']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['准确报出订单信息', '订单异常/质量问题退款', '诱导点击陌生链接', '索要验证码或屏幕共享']::text[],'退款理赔请登录官方App核实；任何人索要验证码、要求共享屏幕的都是诈骗。','骗子冒充电商平台客服，准确报出受害人订单信息后谎称订单异常需要退款，诱导点击陌生链接填写银行卡与验证码，或要求开启屏幕共享远程操作，最终盗取账户资金。'),
('e99416ec-5940-4034-b6e9-49f3a48da938','冒充网课机构，退费需要缴纳保证金诈骗','退费','诈骗','冒充网课机构客服，通知课程可以退费，要求先缴纳保证金，保证金会和学费一起退回，转账之后直接失联。','反诈公开案例',ARRAY['网课退费', '退费保证金', '课程退款']::text[],'http://hn.people.com.cn/n2/2025/0826/c406630-41333223.html','培训机构主动退费？当心落入“课程退费”诈骗陷阱（人民网湖南频道）','2025-08-26','media',ARRAY['机构倒闭可退费', '先交手续费/保证金', '扫码进群下载APP', '验资名义转账']::text[],'退费请通过原购买平台或机构官方渠道申请；要求先交手续费、保证金的一律拒绝。','冒充网课机构客服，通知课程可以退费，要求先缴纳保证金，保证金会和学费一起退回，转账之后直接失联。'),
('d6beb279-e540-45ff-80ad-65ef8ef6853b','冒充网购客服谎称商品丢失理赔','冒充客服','诈骗','骗子获取购物记录，冒充平台客服，谎称包裹丢失，主动提出高额理赔，诱导受害人提供银行卡号和短信验证码。','反诈公开案例',ARRAY['商品丢失', '理赔退款', '冒充电商']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['准确报出订单信息', '订单异常/质量问题退款', '诱导点击陌生链接', '索要验证码或屏幕共享']::text[],'退款理赔请登录官方App核实；任何人索要验证码、要求共享屏幕的都是诈骗。','骗子获取购物记录，冒充平台客服，谎称包裹丢失，主动提出高额理赔，诱导受害人提供银行卡号和短信验证码。'),
('3748862c-eb0d-43d2-9548-7e6fe821b1cd','冒充网购客服谎称商品质量问题退款','冒充客服','诈骗','骗子获取网购订单信息，冒充平台客服，说商品存在质量问题要给用户理赔退款，发送虚假链接，诱导填写银行卡、验证码，盗取账户资金。','反诈公开案例',ARRAY['退款理赔', '冒充客服', '验证码', '虚假链接']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['准确报出订单信息', '订单异常/质量问题退款', '诱导点击陌生链接', '索要验证码或屏幕共享']::text[],'退款理赔请登录官方App核实；任何人索要验证码、要求共享屏幕的都是诈骗。','骗子获取网购订单信息，冒充平台客服，说商品存在质量问题要给用户理赔退款，发送虚假链接，诱导填写银行卡、验证码，盗取账户资金。'),
('e8001cd0-113d-4021-8f1c-07754d39912a','冒充网贷客服，征信洗白贷款诈骗','贷款','诈骗','声称可以帮助洗白不良征信，办理低息大额贷款，需要缴纳服务费、征信修复费，交钱之后贷款永远下不来。','反诈公开案例',ARRAY['征信洗白', '网贷服务费', '修复征信']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['低息无抵押诱导', '放款前收费', '解冻金/保证金', '刷流水验资']::text[],'办理贷款请走银行或持牌机构官方渠道；放款前要求缴费、验资、刷流水的，一律是诈骗。','声称可以帮助洗白不良征信，办理低息大额贷款，需要缴纳服务费、征信修复费，交钱之后贷款永远下不来。'),
('fd90ee7d-0c2a-45f9-85d4-d13c204ef15f','冒充航空理赔员以航班延误理赔为名骗取银行卡密码','机票退改签','诈骗','旅客收到航班延误可理赔的短信，联系所谓客服后告知了银行卡号与密码。对方随后以卡内余额不足、不满足赔付标准为由，要求旅客通过网贷平台贷款五万元用于“验资”，旅客在列车上按指引进行人脸识别时被乘警发现并制止。','央视新闻曝光案例（光明网转载）',ARRAY['航班延误', '理赔', '银行卡密码', '网贷']::text[],'https://m.gmw.cn/2026-01/07/content_1304294170.htm','从“赔你钱”到“让你贷” 总台曝光机票退改签诈骗（央视新闻）','2026-01-07','media',ARRAY['伪造航班延误理赔通知', '索要银行卡号与密码', '以余额不足为由诱导网贷']::text[],'航空公司理赔不会索要银行卡密码，也不会要求贷款验资；接到此类电话请挂断并通过官方渠道核实。','您的航班延误可以理赔，但卡内余额不足，需要先贷款验资'),
('f5340657-837a-4f3d-9ba8-a3fd8237353d','冒充证券平台KYC身份更新诈骗','KYC','诈骗','冒充股票证券平台，通知KYC身份资料过期，需要跳转外部网页更新身份，套取银行卡和交易密码。','反诈公开案例',ARRAY['证券KYC', '身份更新', '交易密码泄露']::text[],'https://news.youth.cn/fzlm/202605/t20260528_16684058.htm','刷个脸，竟卷入跨境诈骗大案（中国青年网）','2026-05-28','media',ARRAY['账户信息不全将被冻结', '跳转外部页面补全', '采集人脸与银行卡', '要求转账做流水核验']::text[],'实名认证只在官方App内完成；不会要求转账，也不会通过外部链接采集人脸信息。','冒充股票证券平台，通知KYC身份资料过期，需要跳转外部网页更新身份，套取银行卡和交易密码。'),
('44cb14a0-05ab-4f90-a34d-e7f375f9dfe5','冒充银行KYC身份核验，要求转账核验流水','KYC','诈骗','冒充银行通知KYC身份核验不通过，账户会被冻结，要求转账到指定账户做流水核验，转账之后资金被骗走。','反诈公开案例',ARRAY['银行KYC', '流水核验', '账户冻结威胁']::text[],'https://news.youth.cn/fzlm/202605/t20260528_16684058.htm','刷个脸，竟卷入跨境诈骗大案（中国青年网）','2026-05-28','media',ARRAY['账户信息不全将被冻结', '跳转外部页面补全', '采集人脸与银行卡', '要求转账做流水核验']::text[],'实名认证只在官方App内完成；不会要求转账，也不会通过外部链接采集人脸信息。','冒充银行通知KYC身份核验不通过，账户会被冻结，要求转账到指定账户做流水核验，转账之后资金被骗走。'),
('e0a68c2c-ba89-40c1-8d91-f92b401ce853','冒充银行贷款专员，验资转账诈骗','贷款','诈骗','冒充银行信贷工作人员，说可以办理大额信用贷，要求往银行卡转账做资金验资，验资资金直接被转走。','反诈公开案例',ARRAY['银行信贷', '资金验资', '贷款专员冒充']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['低息无抵押诱导', '放款前收费', '解冻金/保证金', '刷流水验资']::text[],'办理贷款请走银行或持牌机构官方渠道；放款前要求缴费、验资、刷流水的，一律是诈骗。','冒充银行信贷工作人员，说可以办理大额信用贷，要求往银行卡转账做资金验资，验资资金直接被转走。'),
('0be19e4d-0ba1-4892-9422-032988e6a91e','冒充领导侄子以安排工作需要打点费为由诈骗','冒充熟人','诈骗','嫌疑人营造出手阔绰、背景深厚的形象，下载领导照片谎称是其叔叔，并以另外两个微信号分别冒充“当领导的叔叔”和“秘书”。以帮助安排工作需要打点关系、办理手续为由，先后骗取受害人十一万余元。','中国警察网通报案例',ARRAY['冒充领导', '安排工作', '打点关系', '多重身份']::text[],'https://daan.cpd.com.cn/dajs/825/t_1197794.html','一人分饰三角，男子专门“杀熟”（中国警察网-人民公安报）','2025-08-22','official',ARRAY['虚构领导亲属身份', '多账号分饰角色', '以安排工作为诱饵', '层层索要打点费']::text[],'国家机关和事业单位招录有公开程序，不存在“内部安排”；凡是自称领导亲属能办事并索要钱财的，一律是诈骗。','我叔叔是某领导，能给你安排工作，先拿点钱打点关系、办手续'),
('aeee1fb6-2b13-4b3d-931a-717e26064b98','刷单任务卡单需要解冻资金诈骗','刷单','诈骗','受害人做完刷单任务，骗子谎称任务卡单，账户异常，需要转账缴纳解冻金才能把本金佣金全部取出，交完继续编造理由要钱。','反诈公开案例',ARRAY['卡单', '解冻金', '刷单提现失败']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['小额返利建立信任', '诱导大额垫付', '以任务卡单/冻结拒返款', '脱离平台私下转账']::text[],'任何要求先垫付本金的兼职刷单都是诈骗；不要为陌生任务充值转账，发现被骗立即报警。','受害人做完刷单任务，骗子谎称任务卡单，账户异常，需要转账缴纳解冻金才能把本金佣金全部取出，交完继续编造理由要钱。'),
('f6796554-6f23-49a2-b5ce-e817a36bb76f','刷单返利，小额返利诱导大额投入','刷单','诈骗','骗子通过社交软件发布刷单兼职广告，先给小额任务返还佣金获取信任，之后下发大额连单任务，要求不断充值垫付，之后以任务未完成、冻结资金为由拒绝返还本金与佣金，最后拉黑失联。','反诈公开案例',ARRAY['刷单', '兼职', '垫付', '返利']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['小额返利建立信任', '诱导大额垫付', '以任务卡单/冻结拒返款', '脱离平台私下转账']::text[],'任何要求先垫付本金的兼职刷单都是诈骗；不要为陌生任务充值转账，发现被骗立即报警。','骗子通过社交软件发布刷单兼职广告，先给小额任务返还佣金获取信任，之后下发大额连单任务，要求不断充值垫付，之后以任务未完成、冻结资金为由拒绝返还本金与佣金，最后拉黑失联。'),
('e4a5d9c5-63a4-4418-98a2-b8b55cae62df','刷单返利冒充客服办理提现诈骗','刷单','诈骗','刷单平台拒绝提现，冒充平台客服联系受害人，声称缴纳手续费即可开通提现权限，转账之后直接失联。','反诈公开案例',ARRAY['冒充客服', '提现手续费', '刷单平台']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['小额返利建立信任', '诱导大额垫付', '以任务卡单/冻结拒返款', '脱离平台私下转账']::text[],'任何要求先垫付本金的兼职刷单都是诈骗；不要为陌生任务充值转账，发现被骗立即报警。','刷单平台拒绝提现，冒充平台客服联系受害人，声称缴纳手续费即可开通提现权限，转账之后直接失联。'),
('a1dfeb10-797e-4597-b21d-68ad571e5b7f','小红书评论点赞刷单骗局','刷单','诈骗','在小红书私信招募点赞评论员，简单任务给小额红包，之后跳转外部APP做刷单任务，诱导银行卡转账垫资。','反诈公开案例',ARRAY['小红书', '点赞任务', '外部APP']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['小额返利建立信任', '诱导大额垫付', '以任务卡单/冻结拒返款', '脱离平台私下转账']::text[],'任何要求先垫付本金的兼职刷单都是诈骗；不要为陌生任务充值转账，发现被骗立即报警。','在小红书私信招募点赞评论员，简单任务给小额红包，之后跳转外部APP做刷单任务，诱导银行卡转账垫资。'),
('2cafbf32-cd62-4883-ba6c-7a8313c6e396','工商银行官方储蓄卡消费提醒','银行','安全','【中国工商银行】您尾号8877的储蓄卡于10月20日14:32消费人民币128.00元。如非本人操作，请拨打官方客服95588或通过手机银行核实，我行不会索要验证码或要求转账。','银行官方通知样例',ARRAY['银行', '短信提醒', '工行', '官方客服']::text[],NULL,'自建安全案例',NULL,'seed',ARRAY['官方短信格式', '客服号码与官网一致', '不索要验证码', '不要求转账']::text[],'银行不会索要验证码或要求转账；有疑问请拨打银行卡背面的官方客服电话。','【中国工商银行】您尾号8877的储蓄卡于10月20日14:32消费人民币128.00元。如非本人操作，请拨打官方客服95588或通过手机银行核实，我行不会索要验证码或要求转账。'),
('6738618c-ed38-4316-8314-8ccdd24b0093','建设银行账户余额变动通知','银行','安全','【中国建设银行】您尾号6621的账户10月20日入账工资人民币8600.00元，余额23150.42元。查询详单请使用官方手机银行，勿点击短信中的陌生链接。','银行官方通知样例',ARRAY['银行', '余额变动', '建行']::text[],NULL,'自建安全案例',NULL,'seed',ARRAY['官方短信格式', '客服号码与官网一致', '不索要验证码', '不要求转账']::text[],'银行不会索要验证码或要求转账；有疑问请拨打银行卡背面的官方客服电话。','【中国建设银行】您尾号6621的账户10月20日入账工资人民币8600.00元，余额23150.42元。查询详单请使用官方手机银行，勿点击短信中的陌生链接。'),
('00e3ae4b-606e-4986-b974-5416c899b87f','微信群刷单抢红包陷阱','刷单','诈骗','受害人被拉入微信群，群内发红包吸引加入，诱导下载内部刷单APP，前期小额提现成功，后续组合大单要求连续转账，以操作失误冻结账号拒绝回款。','反诈公开案例',ARRAY['微信群刷单', '连单任务', '账号冻结']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['小额返利建立信任', '诱导大额垫付', '以任务卡单/冻结拒返款', '脱离平台私下转账']::text[],'任何要求先垫付本金的兼职刷单都是诈骗；不要为陌生任务充值转账，发现被骗立即报警。','受害人被拉入微信群，群内发红包吸引加入，诱导下载内部刷单APP，前期小额提现成功，后续组合大单要求连续转账，以操作失误冻结账号拒绝回款。'),
('ff02497b-69dd-4606-a27b-b3cfd3a08b79','快递已放入丰巢柜的取件通知','正常服务','安全','您的快递已放入小区丰巢智能柜，取件码8842，请在24小时内凭码取件。取件不需要支付任何费用，也不需要点击链接填写个人信息。','物流正常通知样例',ARRAY['快递', '取件码', '正常派送']::text[],NULL,'自建安全案例',NULL,'seed',ARRAY['官方渠道通知', '不索取资金与凭证', '无陌生链接', '无需转账']::text[],'此类通知无需操作；如遇要求转账或索要验证码的同类信息，请通过官方渠道核实。','您的快递已放入小区丰巢智能柜，取件码8842，请在24小时内凭码取件。取件不需要支付任何费用，也不需要点击链接填写个人信息。'),
('e5320a26-27e8-425b-8e41-e5ad6e23cf54','快递短信带钓鱼链接理赔诈骗','快递理赔','诈骗','收到短信，你的快递损毁点击链接领取理赔金，点开是钓鱼网页，输入银行卡密码就被盗刷。','反诈公开案例',ARRAY['快递短信', '钓鱼短链接', '损毁理赔']::text[],'http://www.pazjw.gov.cn/shuoan/202609/t20260927_31936970.shtml','“三倍理赔”有猫腻 假客服设真骗局（人民公安报，平安浙江网转载）','2026-09-27','official',ARRAY['冒充快递客服', '主动高额理赔', '钓鱼链接/陌生APP', '索要银行卡与验证码']::text[],'快递理赔由寄件方与快递公司处理；接到主动理赔电话请挂断并登录官方物流平台核实。','收到短信，你的快递损毁点击链接领取理赔金，点开是钓鱼网页，输入银行卡密码就被盗刷。'),
('9ed3825a-de85-41a0-8d96-8a2f95c7e079','快递破损理赔，诱导下载陌生APP诈骗','快递理赔','诈骗','骗子冒充快递，说包裹运输破损，要给理赔，不让用官方APP，诱导下载第三方陌生软件办理理赔，窃取手机信息。','反诈公开案例',ARRAY['包裹破损', '第三方APP', '快递理赔']::text[],'http://www.pazjw.gov.cn/shuoan/202609/t20260927_31936970.shtml','“三倍理赔”有猫腻 假客服设真骗局（人民公安报，平安浙江网转载）','2026-09-27','official',ARRAY['冒充快递客服', '主动高额理赔', '钓鱼链接/陌生APP', '索要银行卡与验证码']::text[],'快递理赔由寄件方与快递公司处理；接到主动理赔电话请挂断并登录官方物流平台核实。','骗子冒充快递，说包裹运输破损，要给理赔，不让用官方APP，诱导下载第三方陌生软件办理理赔，窃取手机信息。'),
('279d7ae2-8c9e-4629-ba9c-dfc8a1a28684','恐吓医保卡涉嫌套现需转账解冻','医保社保','诈骗','骗子谎称受害人“不解除每年会扣款”“医保卡涉嫌套现、违规报销”“医保资料缺失将被暂停使用”，以冻结账户相威胁，诱导受害人联系所谓客服并转账“解冻”，从而骗取钱财。','淮北市公安局警情提示',ARRAY['医保套现', '账户冻结', '转账解冻', '恐吓']::text[],'https://gaj.huaibei.gov.cn/jwzx/jfts/57931954.html','警方提示：别信！医保诈骗新套路！（淮北市公安局）','2025-05-20','official',ARRAY['制造账户冻结恐慌', '虚构违规套现', '诱导转账解冻']::text[],'医保部门不会以冻结账户为由要求转账；凡要求转入“安全账户”或缴纳解冻金的，都是诈骗。','你的医保卡涉嫌违规套现，账户要被冻结，赶紧转钱过来做资金解冻'),
('3cce69ce-62d7-4cdb-8825-9817f8a77fc2','投资群里除受害人外全是托儿','虚假投资理财','诈骗','警方查明，受害人所处的微信聊天群由诈骗团伙操控，群内所谓的导师、助理与晒收益的群友大多是诈托，仅受害人一人是真实投资者。团伙通过操控虚假平台数据制造盈利假象，最终使受害人血本无归。','国家反诈中心十大高发诈骗（晋中市公安局转载）',ARRAY['投资群', '托儿', '虚假盈利', '操控后台']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['群成员多为托', '伪造盈利截图', '后台操控盈亏']::text[],'凡是拉你进群、晒收益、催你入金的“投资群”，都应视为高风险；投资前核实平台是否持牌。','群里大家都在赚钱，就你还在观望'),
('8e7844c5-7438-46ff-8362-26e168c92977','抖音点赞刷单兼职骗局','刷单','诈骗','声称点赞关注短视频即可赚钱，先做简单任务发小红包，后续引导下载陌生APP做刷单任务，需要个人转账垫资，垫资越大损失越高。','反诈公开案例',ARRAY['点赞刷单', '短视频兼职', '陌生APP']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['小额返利建立信任', '诱导大额垫付', '以任务卡单/冻结拒返款', '脱离平台私下转账']::text[],'任何要求先垫付本金的兼职刷单都是诈骗；不要为陌生任务充值转账，发现被骗立即报警。','声称点赞关注短视频即可赚钱，先做简单任务发小红包，后续引导下载陌生APP做刷单任务，需要个人转账垫资，垫资越大损失越高。'),
('1e714776-9601-40cd-ab33-d8ba00680645','招商银行信用卡账单提醒','银行','安全','【招商银行】您尾号3390信用卡本期账单应还人民币2480.00元，到期还款日11月8日。可通过官方掌上生活APP还款，客服热线95555。','银行官方通知样例',ARRAY['银行', '信用卡', '账单', '招行']::text[],NULL,'自建安全案例',NULL,'seed',ARRAY['官方短信格式', '客服号码与官网一致', '不索要验证码', '不要求转账']::text[],'银行不会索要验证码或要求转账；有疑问请拨打银行卡背面的官方客服电话。','【招商银行】您尾号3390信用卡本期账单应还人民币2480.00元，到期还款日11月8日。可通过官方掌上生活APP还款，客服热线95555。'),
('5c2f3cb8-3b5d-4ff3-81b1-74b80f751aaa','招聘兼职刷信誉购物刷单诈骗','刷单','诈骗','网上发布招聘刷信誉兼职，宣称足不出户日赚几百，第一二单返还佣金，后面要求多单联做，不断加大垫付金额，完成后直接拉黑。','反诈公开案例',ARRAY['刷信誉', '网上兼职', '垫付本金']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['小额返利建立信任', '诱导大额垫付', '以任务卡单/冻结拒返款', '脱离平台私下转账']::text[],'任何要求先垫付本金的兼职刷单都是诈骗；不要为陌生任务充值转账，发现被骗立即报警。','网上发布招聘刷信誉兼职，宣称足不出户日赚几百，第一二单返还佣金，后面要求多单联做，不断加大垫付金额，完成后直接拉黑。'),
('7a8ef06b-20d0-4643-9913-84532bb1eec4','政务服务大厅办件进度通知','正常服务','安全','您在市政务服务中心提交的营业执照变更事项已受理，办件编号 20261020001。可在政务服务网或官方小程序查询办理进度，全程不收取任何费用。','公开政务网站说明',ARRAY['政务', '办件进度', '无风险']::text[],NULL,'自建安全案例',NULL,'seed',ARRAY['官方渠道通知', '不索取资金与凭证', '无陌生链接', '无需转账']::text[],'此类通知无需操作；如遇要求转账或索要验证码的同类信息，请通过官方渠道核实。','您在市政务服务中心提交的营业执照变更事项已受理，办件编号 20261020001。可在政务服务网或官方小程序查询办理进度，全程不收取任何费用。'),
('c9a8e449-919c-4acf-899c-74fd19b508d4','政务服务网办理业务安全提醒','正常服务','安全','政务服务网提醒：在本平台办理业务无需提供银行卡号、验证码或支付任何费用。如遇要求转账、索要验证码的短信或电话，请勿理会并通过官方渠道核实。','公开政务网站说明',ARRAY['政务', '安全提醒', '验证码', '劝阻']::text[],NULL,'自建安全案例',NULL,'seed',ARRAY['官方渠道通知', '不索取资金与凭证', '无陌生链接', '无需转账']::text[],'此类通知无需操作；如遇要求转账或索要验证码的同类信息，请通过官方渠道核实。','政务服务网提醒：在本平台办理业务无需提供银行卡号、验证码或支付任何费用。如遇要求转账、索要验证码的短信或电话，请勿理会并通过官方渠道核实。'),
('28562823-b03d-46ea-a2fb-ecb5812939cb','杀猪盘以家庭困难借钱周转实施诈骗','杀猪盘','诈骗','网上恋爱交往一段时间，编造家人重病、生意周转等理由，多次向受害人借钱，拿到钱款之后直接拉黑消失。','反诈公开案例',ARRAY['网恋借钱', '家庭变故', '情感诈骗']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['情感包装建立信任', '虚假投资平台', '前期可提现后无法提现', '内部渠道/博彩漏洞']::text[],'网络交友涉及投资、博彩、内部渠道的一律停止；正规投资不会通过私人关系带你赚钱。','网上恋爱交往一段时间，编造家人重病、生意周转等理由，多次向受害人借钱，拿到钱款之后直接拉黑消失。'),
('0172fb5c-e7e4-435f-bb16-a7a5096414b0','杀猪盘伪装高净值人士诱导虚拟币投资','杀猪盘','诈骗','网上伪装成功人士谈恋爱，取得信任之后，介绍内部虚拟币交易平台，受害人投入大量资金，平台后台人为操控盈亏。','反诈公开案例',ARRAY['虚拟币', '网恋杀猪盘', '虚假交易平台']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['情感包装建立信任', '虚假投资平台', '前期可提现后无法提现', '内部渠道/博彩漏洞']::text[],'网络交友涉及投资、博彩、内部渠道的一律停止；正规投资不会通过私人关系带你赚钱。','网上伪装成功人士谈恋爱，取得信任之后，介绍内部虚拟币交易平台，受害人投入大量资金，平台后台人为操控盈亏。'),
('6ebe178d-5400-4de4-a739-d1aaff3f3fe6','杀猪盘网恋诱导虚假投资平台','杀猪盘','诈骗','社交软件伪装异性交友网恋，建立情感信任之后，诱导进入私设虚假投资网站，前期小额可以提现，大额投入之后平台无法登录，资金全部被骗走。','反诈公开案例',ARRAY['网恋', '虚假投资', '杀猪盘', '交友软件']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['情感包装建立信任', '虚假投资平台', '前期可提现后无法提现', '内部渠道/博彩漏洞']::text[],'网络交友涉及投资、博彩、内部渠道的一律停止；正规投资不会通过私人关系带你赚钱。','社交软件伪装异性交友网恋，建立情感信任之后，诱导进入私设虚假投资网站，前期小额可以提现，大额投入之后平台无法登录，资金全部被骗走。'),
('2c091ce8-a283-48f2-9687-440b27eb7296','杀猪盘诱导受害人帮自己操作投资账号','杀猪盘','诈骗','网恋对象说自己不方便操作投资，把账号密码发给受害人代为操作，让受害人看到高额盈利，引诱受害人自己注册充值。','反诈公开案例',ARRAY['代为操作账号', '虚假盈利诱导', '杀猪盘套路']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['情感包装建立信任', '虚假投资平台', '前期可提现后无法提现', '内部渠道/博彩漏洞']::text[],'网络交友涉及投资、博彩、内部渠道的一律停止；正规投资不会通过私人关系带你赚钱。','网恋对象说自己不方便操作投资，把账号密码发给受害人代为操作，让受害人看到高额盈利，引诱受害人自己注册充值。'),
('0a16d666-0c94-47f6-aded-09eef5bf0a25','校园培训退费诈骗','退费','诈骗','针对大学生，声称网课培训班可以全额退费，添加QQ群，引导下载APP，以验资名义让学生转账。','反诈公开案例',ARRAY['大学生', '网课退费', 'QQ群']::text[],'http://hn.people.com.cn/n2/2025/0826/c406630-41333223.html','培训机构主动退费？当心落入“课程退费”诈骗陷阱（人民网湖南频道）','2025-08-26','media',ARRAY['机构倒闭可退费', '先交手续费/保证金', '扫码进群下载APP', '验资名义转账']::text[],'退费请通过原购买平台或机构官方渠道申请；要求先交手续费、保证金的一律拒绝。','针对大学生，声称网课培训班可以全额退费，添加QQ群，引导下载APP，以验资名义让学生转账。'),
('ac8f87da-a393-4c3d-add0-39044954736c','校园学生QQ群刷单兼职诈骗','刷单','诈骗','骗子潜入高校QQ群发布刷单兼职，瞄准学生零花钱少想赚外快心理，诱导学生用生活费垫付刷单，最后卷钱跑路。','反诈公开案例',ARRAY['大学生', 'QQ群兼职', '生活费垫付']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['小额返利建立信任', '诱导大额垫付', '以任务卡单/冻结拒返款', '脱离平台私下转账']::text[],'任何要求先垫付本金的兼职刷单都是诈骗；不要为陌生任务充值转账，发现被骗立即报警。','骗子潜入高校QQ群发布刷单兼职，瞄准学生零花钱少想赚外快心理，诱导学生用生活费垫付刷单，最后卷钱跑路。'),
('ee35469e-52cc-4a17-94f4-8ab9163ee095','校园虚假网贷，学生缴纳会员费才能放款','贷款','诈骗','面向大学生宣传低息校园贷，申请贷款时，告知需要开通高级会员才能放款，学生缴纳会员费后，平台失联。','反诈公开案例',ARRAY['校园贷', '会员费', '大学生贷款诈骗']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['低息无抵押诱导', '放款前收费', '解冻金/保证金', '刷流水验资']::text[],'办理贷款请走银行或持牌机构官方渠道；放款前要求缴费、验资、刷流水的，一律是诈骗。','面向大学生宣传低息校园贷，申请贷款时，告知需要开通高级会员才能放款，学生缴纳会员费后，平台失联。'),
('96a5b51d-70cd-4653-8951-ac795c30c155','游戏代练赚钱为诱饵的虚假交易诈骗','网络游戏交易','诈骗','诈骗分子以游戏代练、代打可以赚钱为诱饵吸引玩家，随后要求玩家先缴纳保证金或购买指定服务，声称完成任务后一并返还。玩家付款后对方以任务未完成、需要继续投入为由拒绝返款并失联。','公安部刑侦局提示（光明网转载）',ARRAY['游戏代练', '保证金', '返款失败']::text[],'https://m.gmw.cn/2025-07/29/content_1304096705.htm','警方提醒：警惕网络游戏虚假交易类诈骗（公安部刑侦局）','2025-07-29','official',ARRAY['代练兼职为诱饵', '缴纳保证金', '以任务未完成为由拒返款']::text[],'游戏代练类兼职多与诈骗、盗号风险相关，切勿向陌生方缴纳保证金或提供账号密码。','做代练一天能赚几百，先交保证金，做完一起返'),
('192d9e36-bbb5-4e7f-9838-3bdd504c8ac2','游戏内弹窗中奖，诱导转账领奖诈骗','中奖','诈骗','游戏聊天窗口弹出恭喜中奖，发送QQ联系领奖客服，客服以领奖手续费、激活费为由不断要钱。','反诈公开案例',ARRAY['游戏中奖弹窗', '领奖客服', '激活费用']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['天降中奖通知', '领奖前先收费', '运费/税费/保证金', '仿冒品牌公众号']::text[],'正规抽奖不会要求先交运费、税费或保证金；不要点击短信中的领奖链接。','游戏聊天窗口弹出恭喜中奖，发送QQ联系领奖客服，客服以领奖手续费、激活费为由不断要钱。'),
('ba076019-acf9-4485-b581-a929e8178332','电商平台官方订单发货通知','正常服务','安全','您的订单已发货，物流单号 SF1234567890，可在官方APP内查看物流详情。平台不会以订单异常为由要求您点击外部链接或提供验证码。','电商平台通知样例',ARRAY['电商', '发货通知', '官方APP', '物流']::text[],NULL,'自建安全案例',NULL,'seed',ARRAY['官方渠道通知', '不索取资金与凭证', '无陌生链接', '无需转账']::text[],'此类通知无需操作；如遇要求转账或索要验证码的同类信息，请通过官方渠道核实。','您的订单已发货，物流单号 SF1234567890，可在官方APP内查看物流详情。平台不会以订单异常为由要求您点击外部链接或提供验证码。'),
('08f8d897-32f1-46cb-8448-f648a8a6cb11','电商店铺好评刷单返利陷阱','刷单','诈骗','宣称给淘宝店铺写好评拿佣金，初期小额返利，后续引导脱离平台私下转账垫付，不经过电商官方交易。','反诈公开案例',ARRAY['好评刷单', '脱离平台', '私下转账']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['小额返利建立信任', '诱导大额垫付', '以任务卡单/冻结拒返款', '脱离平台私下转账']::text[],'任何要求先垫付本金的兼职刷单都是诈骗；不要为陌生任务充值转账，发现被骗立即报警。','宣称给淘宝店铺写好评拿佣金，初期小额返利，后续引导脱离平台私下转账垫付，不经过电商官方交易。'),
('738710d3-f4f9-47c7-98b9-9b73bf40b5f7','盗用朋友头像加好友以代付礼品钱为由骗十八万','冒充熟人','诈骗','受害人收到头像与朋友一致的微信好友申请，通过后对方称要给领导送礼、希望其代为支付礼品款，并发来银行卡账户。受害人未进一步核实即转账十八万元，随后对方又以需要继续转账为由反复索要，直至当面询问朋友才知被骗。','国家反诈中心十大高发诈骗（晋中市公安局转载）',ARRAY['冒充熟人', '盗用头像', '代付', '转账']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['盗用熟人头像昵称', '编造送礼等紧急事由', '提供陌生收款账户']::text[],'凡是通过微信、QQ、短信要求转账的，务必电话或当面核实；头像和昵称都可以伪造。','我这边不方便转账，你先帮我垫一下，晚点还你'),
('f8a207db-b9c7-40db-916a-1fe3c3d425bf','直播平台关注刷数据刷单诈骗','刷单','诈骗','宣称帮直播间涨粉刷数据可以赚钱，先小额结算，之后要求大额充值解锁高级任务，充值之后无法提现。','反诈公开案例',ARRAY['直播间刷数据', '涨粉任务', '解锁高级任务']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['小额返利建立信任', '诱导大额垫付', '以任务卡单/冻结拒返款', '脱离平台私下转账']::text[],'任何要求先垫付本金的兼职刷单都是诈骗；不要为陌生任务充值转账，发现被骗立即报警。','宣称帮直播间涨粉刷数据可以赚钱，先小额结算，之后要求大额充值解锁高级任务，充值之后无法提现。'),
('fd460a53-a9eb-4046-b9e0-3cd722a60f86','直播间购物送抽奖，中奖后奖品永不发货','虚假购物','诈骗','受害人在直播间看到“购物送抽奖、中奖率百分百”的广告，花一千一百元购买化妆品并抽中平板电脑，但迟迟收不到奖品，联系主播也未获答复。警方研判认定该主播涉嫌以抽奖为名实施诈骗。','国家反诈中心十大高发诈骗（晋中市公安局转载）',ARRAY['直播带货', '抽奖', '虚假购物', '不发货']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['中奖率百分百为诱饵', '诱导高价购物', '奖品不发货']::text[],'对“购物必中奖”“百分百中奖”等宣传保持警惕；购物请通过正规电商平台并保留交易凭证。','今天下单百分百中奖，奖品马上安排发货'),
('37de1328-2f45-41ff-8ceb-ab78a470d169','短信称医保卡停用需点击链接验证身份','医保社保','诈骗','不法分子群发短信，称“医保卡已停用，点击链接验证身份”“医保账户需升级，请完善信息”“医保资料缺失将被暂停使用”，诱导参保人点击短信中的钓鱼链接，进入仿冒页面填写身份证、银行卡与验证码。','淮北市公安局警情提示',ARRAY['医保卡停用', '钓鱼链接', '身份验证', '短信']::text[],'https://gaj.huaibei.gov.cn/jwzx/jfts/57931954.html','警方提示：别信！医保诈骗新套路！（淮北市公安局）','2025-05-20','official',ARRAY['伪造医保停用通知', '短信钓鱼链接', '套取身份与银行卡信息']::text[],'医保电子凭证状态以官方App查询为准；短信中的链接不要点击，更不要在陌生页面填写验证码。','您的医保卡已停用，请点击链接验证身份，否则将影响使用'),
('09697afa-a431-45e4-a112-7860a01bddbe','短信通知中奖，需要先交税费才能领奖','中奖','诈骗','短信告知用户中大奖，奖品为手机、现金等，但是需要先缴纳个税、保证金、手续费，转账之后对方直接消失。','反诈公开案例',ARRAY['中奖', '手续费', '保证金', '领奖']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['天降中奖通知', '领奖前先收费', '运费/税费/保证金', '仿冒品牌公众号']::text[],'正规抽奖不会要求先交运费、税费或保证金；不要点击短信中的领奖链接。','短信告知用户中大奖，奖品为手机、现金等，但是需要先缴纳个税、保证金、手续费，转账之后对方直接消失。'),
('66eb7075-2819-4ff1-9206-862d3a093a4e','短视频弹窗中奖，填写信息缴纳领奖保证金','中奖','诈骗','刷短视频弹出中奖弹窗，提示抽中手机平板，点击跳转网页，要求缴纳保证金才能领取奖品，无任何实物发放。','反诈公开案例',ARRAY['短视频弹窗', '中奖弹窗', '领奖保证金']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['天降中奖通知', '领奖前先收费', '运费/税费/保证金', '仿冒品牌公众号']::text[],'正规抽奖不会要求先交运费、税费或保证金；不要点击短信中的领奖链接。','刷短视频弹出中奖弹窗，提示抽中手机平板，点击跳转网页，要求缴纳保证金才能领取奖品，无任何实物发放。'),
('ce7a3c01-9588-492d-b2ca-1d520a572ff7','社交软件相亲杀猪盘，诱导博彩平台充值','杀猪盘','诈骗','相亲交友软件认识对象，确立恋爱关系，透露自己掌握博彩平台漏洞，带受害人一起赚钱，充值之后无法提现。','反诈公开案例',ARRAY['相亲软件', '博彩漏洞', '杀猪盘博彩']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['情感包装建立信任', '虚假投资平台', '前期可提现后无法提现', '内部渠道/博彩漏洞']::text[],'网络交友涉及投资、博彩、内部渠道的一律停止；正规投资不会通过私人关系带你赚钱。','相亲交友软件认识对象，确立恋爱关系，透露自己掌握博彩平台漏洞，带受害人一起赚钱，充值之后无法提现。'),
('20590c09-5c00-46d6-8ca5-7037352e0914','线下现金交接规避监管的投资理财诈骗','虚假投资理财','诈骗','警方在侦办一起投资理财诈骗案时发现，嫌疑人收取现金后正准备接手下一笔。受害人已从银行取出十六万元现金，在小区内准备交给自称“张经理”的嫌疑人，所幸被民警当场拦截，现金完好无损。','人民网四川频道报道',ARRAY['线下交付', '现金', '投资理财', '警方拦截']::text[],'http://sc.people.com.cn/n2/2025/1115/c345509-41412377.html','警惕！虚假投资理财诈骗成新套路（人民网四川频道）','2025-11-15','media',ARRAY['要求现金交易规避监管', '线下专人收钱', '以高收益麻痹受害人']::text[],'凡是要求取现、线下交付现金的“投资”，都是诈骗的典型特征；遇到此类要求应立即停止并报警。','现金交给我们经理，线下操作收益更高，也不用走银行流水'),
('3ed29dc1-a3d0-4c7d-8a4e-92ce5ca76d52','网络低息贷款，先交保证金解冻金','贷款','诈骗','广告宣传低息无抵押网贷，提交资料之后，骗子说银行卡号错误账户冻结，要求缴纳解冻金、保证金，交完依旧不放款。','反诈公开案例',ARRAY['网贷', '解冻金', '保证金', '银行卡错误']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['低息无抵押诱导', '放款前收费', '解冻金/保证金', '刷流水验资']::text[],'办理贷款请走银行或持牌机构官方渠道；放款前要求缴费、验资、刷流水的，一律是诈骗。','广告宣传低息无抵押网贷，提交资料之后，骗子说银行卡号错误账户冻结，要求缴纳解冻金、保证金，交完依旧不放款。'),
('34b29134-c45b-429d-9855-66a246a09806','网贷审批失败，缴纳刷流水费用诈骗','贷款','诈骗','网贷申请提示审批不通过，骗子说帮忙刷流水提高通过率，要求受害人转账刷流水，刷完直接失联。','反诈公开案例',ARRAY['贷款刷流水', '审批失败', '刷流水服务费']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['低息无抵押诱导', '放款前收费', '解冻金/保证金', '刷流水验资']::text[],'办理贷款请走银行或持牌机构官方渠道；放款前要求缴费、验资、刷流水的，一律是诈骗。','网贷申请提示审批不通过，骗子说帮忙刷流水提高通过率，要求受害人转账刷流水，刷完直接失联。'),
('288dc1a7-ae62-4682-bf4b-5c0bd26e1aa2','荐股群导师推荐优股致受害人投入七十六万无法提现','虚假投资理财','诈骗','受害人对投资理财文章产生兴趣后添加所谓导师助理，被拉入投资讲解微信群并安装指定理财软件。群内“导师”每日推荐股票，多人称收益可观，受害人先后分八笔投入七十六万元，账面盈利二百万元，准备提现时发现无法操作并被拉黑。','国家反诈中心十大高发诈骗（晋中市公安局转载）',ARRAY['荐股群', '导师', '虚假理财APP', '无法提现']::text[],'http://gaj.sxjz.gov.cn/site/Public/showinfo.aspx?id=2021020518020938250107','国家反诈中心提醒：警惕十大高发诈骗（晋中市公安局转载）','2025-06-11','official',ARRAY['冒充投资导师', '群内托儿造势', '指定理财软件', '提现受阻后拉黑']::text[],'荐股群、投资群里的“导师”和“学员”多为托儿；正规证券投资不使用来路不明的理财软件。','跟着导师买，稳赚不赔，下载这个软件一起操作'),
('c851b676-13de-414c-b9f3-27b91f200553','虚假民航局网站配合专用App与NFC盗刷二十万','机票退改签','诈骗','受害人接到自称航空公司保险理赔员的电话，称可免费改签并理赔。受害人点击对方提供的网址进入仿冒平台，客服又发来新链接，要求确认收款银行卡、开启手机NFC“碰一碰”、下载名为“card2.0”的专用App，并向公众号发送理赔信息、输入银行卡密码。操作中手机黑屏数十秒，随后发现银行卡少了二十万元。','央视新闻曝光案例（光明网转载）',ARRAY['虚假民航网站', 'NFC', '专用App', '盗刷']::text[],'https://m.gmw.cn/2026-01/07/content_1304294170.htm','从“赔你钱”到“让你贷” 总台曝光机票退改签诈骗（央视新闻）','2026-01-07','media',ARRAY['仿冒民航局或航司网站', '要求开启NFC功能', '诱导安装专用App', '索要银行卡密码']::text[],'退改签请通过航空公司官网或官方App办理；不要在陌生页面开启NFC、安装不明App或输入银行卡密码。','打开NFC碰一碰，再装个card2.0登记银行卡，退款马上到账'),
('9359f998-fad8-472d-8962-934b9f02324e','警方反诈宣传提示','正常服务','安全','警方提示：凡是要求把钱转入所谓安全账户接受资金清查的，都是诈骗；凡是索要验证码、银行卡密码的，都是诈骗。请勿轻信陌生来电，如遇可疑情况请拨打110或96110咨询。','官方公共服务样例',ARRAY['警方提示', '反诈宣传', '安全账户', '劝阻']::text[],NULL,'自建安全案例',NULL,'seed',ARRAY['官方渠道通知', '不索取资金与凭证', '无陌生链接', '无需转账']::text[],'此类通知无需操作；如遇要求转账或索要验证码的同类信息，请通过官方渠道核实。','警方提示：凡是要求把钱转入所谓安全账户接受资金清查的，都是诈骗；凡是索要验证码、银行卡密码的，都是诈骗。请勿轻信陌生来电，如遇可疑情况请拨打110或96110咨询。'),
('4404b6b5-74b4-4ac1-aa80-317a250163ac','语音合成伪造对话谎称获巨额拆迁款','AI换脸','诈骗','被告人使用录音合成软件制作虚假对话，谎称自己将获得巨额拆迁款，以此让受害人相信其还款能力，诱使受害人多次转账并为其购买高端手机，财物得手后立即失联。','人民法院报案例（忻府区法院转载）',ARRAY['语音合成', '拆迁款', '虚假对话', '借款']::text[],'https://xzxffy.shanxify.gov.cn/article/detail/2025/11/id/9091051.shtml','利用“AI换脸”诈骗网恋对象 女子被判刑罚（人民法院报）','2025-11-28','official',ARRAY['语音合成伪造对话', '虚构大额收入来源', '以还款能力骗取信任']::text[],'声音同样可以被合成，听到“熟人”声音要求转账时应挂断并回拨核实；任何借款都应留存书面凭证。','我家马上拆迁，补偿款一下来就还你，先帮我垫一下'),
('1bf56d25-77d7-483f-a551-16c81bf6fdc6','谎称代办大专毕业证收取办证费用','冒充熟人','诈骗','嫌疑人在为他人“安排工作”的过程中，被问及能否办理大专毕业证时满口答应，借机收取七千余元办证费用，实际上并未办理任何证件，钱款被其占为己有。','中国警察网通报案例',ARRAY['办证诈骗', '学历证书', '熟人介绍']::text[],'https://daan.cpd.com.cn/dajs/825/t_1197794.html','一人分饰三角，男子专门“杀熟”（中国警察网-人民公安报）','2025-08-22','official',ARRAY['承诺办理学历证件', '收取费用不办事', '依托熟人信任']::text[],'学历证书只能通过正规教育渠道取得，任何“花钱办证”都是诈骗，且买卖证件本身违法。','毕业证我能办，交点钱和材料就行'),
('c5c0fb0b-f758-4a86-81c2-ddeb83520117','运营商套餐流量使用提醒','正常服务','安全','【中国移动】您本月套餐内流量已使用85%，剩余3.2GB。可登录中国移动官方APP查询详单，无需点击短信中的任何链接。','运营商通知样例',ARRAY['运营商', '流量提醒', '官方APP']::text[],NULL,'自建安全案例',NULL,'seed',ARRAY['官方渠道通知', '不索取资金与凭证', '无陌生链接', '无需转账']::text[],'此类通知无需操作；如遇要求转账或索要验证码的同类信息，请通过官方渠道核实。','【中国移动】您本月套餐内流量已使用85%，剩余3.2GB。可登录中国移动官方APP查询详单，无需点击短信中的任何链接。'),
('1e7a9149-b89e-4919-b7cc-3afda8a6c9a9','银行官方APP下载与安全提示','银行','安全','请通过手机应用商店或银行官方网站下载手机银行客户端。银行不会通过短信链接要求您下载安装包，也不会索取登录密码、短信验证码或要求向安全账户转账。','银行官方通知样例',ARRAY['银行', 'APP', '安全提示', '官方渠道']::text[],NULL,'自建安全案例',NULL,'seed',ARRAY['官方短信格式', '客服号码与官网一致', '不索要验证码', '不要求转账']::text[],'银行不会索要验证码或要求转账；有疑问请拨打银行卡背面的官方客服电话。','请通过手机应用商店或银行官方网站下载手机银行客户端。银行不会通过短信链接要求您下载安装包，也不会索取登录密码、短信验证码或要求向安全账户转账。'),
('6710f950-e9c2-4f36-870c-9bfc7bd83adc','银行官方反诈提醒短信','正常服务','安全','【中国工商银行】请勿向他人透露短信验证码、银行卡密码及身份证号。银行工作人员不会以任何理由索要您的验证码或要求向陌生账户转账。如遇可疑情况请拨打官方客服95588核实。','银行官方通知样例',ARRAY['银行', '反诈提醒', '验证码', '劝阻']::text[],NULL,'自建安全案例',NULL,'seed',ARRAY['官方渠道通知', '不索取资金与凭证', '无陌生链接', '无需转账']::text[],'此类通知无需操作；如遇要求转账或索要验证码的同类信息，请通过官方渠道核实。','【中国工商银行】请勿向他人透露短信验证码、银行卡密码及身份证号。银行工作人员不会以任何理由索要您的验证码或要求向陌生账户转账。如遇可疑情况请拨打官方客服95588核实。'),
('51bd51a2-06c6-4e01-9938-8a9b5767d2e4','高价收购游戏账号诱导至虚假交易平台收解冻费','网络游戏交易','诈骗','受害人在游戏中收到好友申请，对方提出以三千元高价收购其游戏账号。对方发来网址链接称需通过平台交易，受害人注册后平台显示有三千元冻结资金，需先支付九百元解冻费才能交易，付款后账号仍显示冻结。','公安部刑侦局提示（光明网转载）',ARRAY['游戏账号', '虚假交易平台', '解冻费', '高价收购']::text[],'https://m.gmw.cn/2025-07/29/content_1304096705.htm','警方提醒：警惕网络游戏虚假交易类诈骗（公安部刑侦局）','2025-07-29','official',ARRAY['高价收购为诱饵', '引导至虚假交易平台', '以解冻费名义收费', '继续加收手续费认证金']::text[],'买卖游戏账号、道具请使用官方或正规第三方平台；任何要求先交解冻费、手续费、认证金的交易都是诈骗。','你的号我出三千收，走平台交易，先交解冻费就能提现')
